7	export const metadata: Metadata = {
8	  title: "Rankora - AI-Powered Resume Screening",
9	  description:
10	    "Screen and rank resumes in seconds using GPT-4o. Paste a job description, upload resumes, and get AI-powered candidate rankings instantly.",
11	  keywords: [
12	    "resume ranker",
13	    "AI resume screening",
14	    "resume scoring",
15	    "hiring tool",
16	    "recruitment automation",
17	    "ATS",
18	    "applicant tracking",
19	  ],
20	  authors: [{ name: "Rankora" }],
21	  robots: "index, follow",
22	  openGraph: {
23	    type: "website",
24	    title: "Rankora - AI-Powered Resume Screening",
25	    description:
26	      "Screen and rank resumes in seconds using GPT-4o. Paste a job description, upload resumes, and get AI-powered candidate rankings instantly.",
27	    siteName: "Rankora",
28	    images: [
29	      "https://pub-bb2e103a32db4e198524a2e9ed8f35b4.r2.dev/8866adbf-82a9-49f0-b833-0aa54e4b006a/id-preview-d52e7914--a9db58a3-cf4a-466e-9c81-889096bf5024.lovable.app-1771166124703.png",
30	    ],
31	  },
32	  twitter: {
33	    card: "summary_large_image",
34	    title: "Rankora - AI-Powered Resume Screening",
35	    description:
36	      "Screen and rank resumes in seconds using GPT-4o. Paste a job description, upload resumes, and get AI-powered candidate rankings instantly.",
37	    images: [
38	      "https://pub-bb2e103a32db4e198524a2e9ed8f35b4.r2.dev/8866adbf-82a9-49f0-b833-0aa54e4b006a/id-preview-d52e7914--a9db58a3-cf4a-466e-9c81-889096bf5024.lovable.app-1771166124703.png",
39	    ],
40	  },
41	};
42	
43	export const viewport: Viewport = {
44	  width: "device-width",
45	  initialScale: 1,
46	  themeColor: "#8b5cf6",
47	};
48	
49	const themeInitScript = `(function() {
50	  var theme = localStorage.getItem('rankora-theme');
51	  if (theme === 'dark') {
52	    document.documentElement.classList.add('dark');
53	    document.documentElement.style.colorScheme = 'dark';
54	  }
55	})();`;
56	
57	export default async function RootLayout({
58	  children,
59	}: {
60	  children: React.ReactNode;
61	}) {
62	  // Resolve the initial user server-side so the first HTML response
63	  // already reflects the correct auth state. Eliminates the logged-out →
64	  // logged-in flash on full page loads.
65	  const initialUser = await getOptionalUser();
66	
67	  return (
68	    <html lang="en" suppressHydrationWarning>
69	      <head>
70	        <Script
71	          id="theme-init"
72	          strategy="beforeInteractive"
73	          dangerouslySetInnerHTML={{ __html: themeInitScript }}
74	        />
75	      </head>
76	      <body>
77	        <Providers initialUser={initialUser}>{children}</Providers>
78	      </body>
79	    </html>
80	  );
81	}
