18	interface Benefit {
19	  icon: string;
20	  title: string;
21	  description: string;
22	}
23	
24	interface Testimonial {
25	  quote: string;
26	  name: string;
27	  role: string;
28	  photo_url?: string | null;
29	}
30	
31	interface SocialLinks {
32	  website?: string;
33	  linkedin?: string;
34	  twitter?: string;
35	  instagram?: string;
36	  facebook?: string;
37	}
38	
39	interface CareerConfig {
40	  team_id: string;
41	  company_name: string;
42	  logo_url: string | null;
43	  brand_color: string;
44	  tagline: string | null;
45	  about: string | null;
46	  // Enhanced branding
47	  custom_css: string | null;
48	  cover_image_url: string | null;
49	  // Culture
50	  culture_title: string | null;
51	  culture_description: string | null;
52	  benefits: Benefit[] | null;
53	  testimonials: Testimonial[] | null;
54	  // Social
55	  social_links: SocialLinks | null;
