74	// ---------------------------------------------------------------------------
75	// Helpers
76	// ---------------------------------------------------------------------------
77	
78	function sanitizeCSS(css: string): string {
79	  if (!css) return "";
80	  return css
81	    .replace(/@import\b/gi, "/* blocked @import */")
82	    .replace(/javascript\s*:/gi, "/* blocked */")
83	    .replace(/expression\s*\(/gi, "/* blocked */")
84	    .replace(/behavior\s*:/gi, "/* blocked */")
85	    .replace(/url\s*\(\s*["']?\s*(?!https?:\/\/)/gi, "url(/* blocked */")
86	    .replace(/<\/?script/gi, "/* blocked */");
87	}
88	
89	const iconFallbacks: Record<string, string> = {
90	  Heart: "❤️", Star: "⭐", Zap: "⚡", Globe: "🌍", Shield: "🛡️",
91	  Award: "🏆", Coffee: "☕", Users: "👥", TrendingUp: "📈", Home: "🏠",
92	  Smile: "😊", Clock: "⏰", DollarSign: "💰", Gift: "🎁", Briefcase: "💼",
93	  Laptop: "💻", Plane: "✈️", BookOpen: "📚", Music: "🎵", Camera: "📷",
94	};
95	
96	function BenefitIcon({ name }: { name: string }) {
97	  const emoji = iconFallbacks[name] ?? "✦";
98	  return (
99	    <span className="text-2xl leading-none" role="img" aria-label={name}>
100	      {emoji}
101	    </span>
102	  );
103	}
104	
105	// ---------------------------------------------------------------------------
106	// Subscribe form
