109	function SubscribeSection({ teamId, brandColor }: { teamId: string; brandColor: string }) {
110	  const [email, setEmail] = useState("");
111	  const [submitting, setSubmitting] = useState(false);
112	  const [subscribed, setSubscribed] = useState(false);
113	
114	  const handleSubscribe = async (e: React.FormEvent) => {
115	    e.preventDefault();
116	    if (!email.trim() || !teamId) return;
117	    setSubmitting(true);
118	    try {
119	      const { error } = await (supabase as any)
120	        .from("career_subscribers")
121	        .insert({ team_id: teamId, email: email.trim().toLowerCase() });
122	      if (error) {
123	        if (error.code === "23505") {
124	          toast.info("You're already subscribed to job alerts.");
125	        } else {
126	          throw error;
127	        }
128	      } else {
129	        setSubscribed(true);
130	        toast.success("Subscribed! We'll notify you about new positions.");
131	      }
132	    } catch (err: unknown) {
133	      const msg = err instanceof Error ? err.message : "Failed to subscribe";
134	      toast.error(msg);
135	    } finally {
136	      setSubmitting(false);
137	    }
138	  };
139	
140	  if (subscribed) {
141	    return (
142	      <section className="py-12 border-t border-border bg-muted/30 dark:bg-muted/10">
143	        <div className="max-w-md mx-auto text-center px-4 space-y-2">
144	          <Bell className="h-8 w-8 mx-auto text-primary" />
145	          <h3 className="text-base font-semibold text-foreground dark:text-foreground">You&apos;re subscribed</h3>
146	          <p className="text-sm text-muted-foreground dark:text-muted-foreground">
147	            We&apos;ll email you when new positions are posted.
148	          </p>
149	        </div>
150	      </section>
151	    );
152	  }
153	
154	  return (
155	    <section className="py-12 border-t border-border bg-muted/30 dark:bg-muted/10">
156	      <div className="max-w-md mx-auto text-center px-4">
157	        <Bell className="h-7 w-7 mx-auto text-muted-foreground dark:text-muted-foreground mb-3" />
158	        <h3 className="text-lg font-semibold mb-2 text-foreground dark:text-foreground">Get notified about new positions</h3>
159	        <p className="text-sm text-muted-foreground dark:text-muted-foreground mb-4">
160	          Enter your email and we&apos;ll send you updates when new jobs are posted.
161	        </p>
162	        <form className="flex gap-2" onSubmit={handleSubscribe}>
163	          <Input
164	            type="email"
165	            placeholder="your@email.com"
166	            required
167	            value={email}
168	            onChange={(e) => setEmail(e.target.value)}
169	            disabled={submitting}
170	            className="flex-1"
171	          />
172	          <Button
173	            type="submit"
174	            disabled={submitting || !email.trim()}
175	            style={{ backgroundColor: brandColor }}
176	            className="text-white hover:opacity-90 shrink-0"
177	          >
178	            {submitting ? "Subscribing…" : "Subscribe"}
179	          </Button>
180	        </form>
181	      </div>
182	    </section>
183	  );
184	}
