9	/** Renders HTML embed code and executes any <script> tags within it */
10	function EmbedRenderer({ html }: { html: string }) {
11	  const containerRef = useRef<HTMLDivElement>(null);
12	
13	  useEffect(() => {
14	    const el = containerRef.current;
15	    if (!el) return;
16	
17	    // Sanitize embed HTML — allow iframes and external scripts for booking widgets
18	    const sanitized = DOMPurify.sanitize(html, {
19	      ADD_TAGS: ["script", "iframe"],
20	      ADD_ATTR: ["src", "async", "defer", "allow", "allowfullscreen", "frameborder", "scrolling"],
21	      FORCE_BODY: true,
22	    });
23	
24	    const temp = document.createElement("div");
25	    temp.innerHTML = sanitized;
26	
27	    el.innerHTML = "";
28	    const scripts: HTMLScriptElement[] = [];
29	    Array.from(temp.childNodes).forEach((node) => {
30	      if (node instanceof HTMLScriptElement) {
31	        scripts.push(node);
32	      } else {
33	        el.appendChild(node.cloneNode(true));
34	      }
35	    });
36	
37	    // Only execute scripts with external src — strip inline scripts for safety
38	    scripts.forEach((orig) => {
39	      if (orig.src) {
40	        const script = document.createElement("script");
41	        script.src = orig.src;
42	        script.async = orig.async;
43	        el.appendChild(script);
44	      }
45	    });
46	
47	    return () => {
48	      el.innerHTML = "";
49	    };
50	  }, [html]);
51	
52	  return (
53	    <div
54	      ref={containerRef}
55	      className="w-full min-h-[700px] [&>iframe]:w-full [&>iframe]:min-h-[700px] [&>iframe]:border-0"
56	    />
57	  );
58	}
